head.b:skin:
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#fffaf2;color:#352417;font-family:"Noto Sans Bengali","Nirmala UI",Arial,sans-serif;line-height:1.75}a{text-decoration:none;color:inherit}.wrap{max-width:1280px;margin:auto;padding:0 16px}.top{background:#321d10;color:#fff0dd;font-size:13px;padding:7px 0}.topin{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap}.header{padding:28px 0 20px;text-align:center;background:linear-gradient(135deg,#fffaf2,#f4dfbe)}.logo{font-size:clamp(28px,5vw,50px);font-weight:800;color:#71330d;margin:0}.tag{color:#6e5b48;margin:3px 0 16px}.search{max-width:800px;margin:auto;display:flex;gap:7px}.search input{flex:1;padding:13px 18px;border:1px solid #dfccb2;border-radius:30px;font-size:15px;background:#fff}.search button{border:0;border-radius:30px;background:#813d12;color:#fff;padding:0 23px;font-weight:700;cursor:pointer}.nav{position:sticky;top:0;z-index:50;background:rgba(255,255,255,.97);border-bottom:1px solid #ead8c0;box-shadow:0 3px 12px rgba(50,30,10,.06)}.navin{display:flex;overflow:auto;white-space:nowrap}.nav a{padding:12px 11px;font-size:13px;font-weight:700;color:#5a3217}.nav a:hover{background:#f8ecd9;color:#853b0d}.hero{margin:25px 0;padding:34px 28px;border:1px solid #ead8c0;border-radius:24px;background:radial-gradient(circle at 15% 15%,#fff,#fff3dd 55%,#efd7b1);box-shadow:0 10px 30px rgba(60,35,10,.08)}.hero h2{margin:0 0 7px;color:#71330d;font-size:clamp(24px,4vw,39px)}.hero p{margin:0;color:#604d3a;max-width:950px}.quick{display:grid;grid-template-columns:repeat(5,1fr);gap:11px;margin:18px 0 32px}.q{background:#fff;border:1px solid #ead8c0;border-radius:15px;padding:14px;text-align:center;box-shadow:0 5px 18px rgba(60,35,10,.05)}.q b{display:block;color:#71330d}.q small{color:#776451}.title{display:flex;justify-content:space-between;align-items:end;gap:15px;margin:32px 0 15px}.title h2{margin:0;color:#71330d;font-size:25px}.title span{font-size:12px;color:#7a6855}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.card{background:#fff;border:1px solid #ead8c0;border-radius:18px;padding:19px;box-shadow:0 8px 24px rgba(60,35,10,.06);transition:.18s}.card:hover{transform:translateY(-2px);box-shadow:0 12px 28px rgba(60,35,10,.1)}.card h3{margin:0 0 9px;color:#74340e;font-size:19px}.card ul{margin:0;padding-left:20px;color:#5f4d3a}.card li{margin:4px 0}.card li a:hover{color:#a05218;text-decoration:underline}.badge{display:inline-block;padding:3px 8px;border-radius:20px;background:#f6e6cc;color:#764214;font-size:10px;font-weight:800}.notice{margin:30px 0;padding:18px 20px;border-left:5px solid #b67b2f;background:#fff6e6;border-radius:10px}.blog{display:none!important}.footer{margin-top:50px;background:#321d10;color:#f7e5cf;padding:34px 0}.foot{display:grid;grid-template-columns:2fr 1fr 1fr;gap:25px}.footer h3{color:#fff;margin-top:0}.footer a:hover{text-decoration:underline}.copy{margin-top:20px;padding-top:13px;border-top:1px solid #664832;font-size:12px;color:#d8c0a4}.back{display:none;position:fixed;right:18px;bottom:18px;width:44px;height:44px;border:0;border-radius:50%;background:#813d12;color:#fff;font-size:18px;z-index:60}@media(max-width:950px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}.quick{grid-template-columns:repeat(3,1fr)}.foot{grid-template-columns:1fr 1fr}}@media(max-width:620px){.wrap{padding:0 11px}.topin{justify-content:center}.header{padding:22px 0 16px}.hero{padding:24px 18px}.grid,.foot{grid-template-columns:1fr}.quick{grid-template-columns:repeat(2,1fr)}.nav a{padding:11px 9px;font-size:12px}.search button{padding:0 15px}}


/* CONTENT SYSTEM */
.article-modal{display:none;position:fixed;inset:0;z-index:9999;background:rgba(35,20,10,.62);padding:20px;overflow:auto}
.article-modal.open{display:flex;align-items:flex-start;justify-content:center}
.article-box{width:min(920px,100%);margin:5vh auto;background:#fffaf2;border:1px solid #ead8c0;border-radius:22px;box-shadow:0 25px 70px rgba(30,15,5,.25);overflow:hidden}
.article-head{padding:22px 24px;background:linear-gradient(135deg,#fffaf2,#f4dfbe);border-bottom:1px solid #ead8c0;display:flex;justify-content:space-between;gap:15px;align-items:flex-start}
.article-head h2{margin:0;color:#71330d;font-size:clamp(22px,4vw,32px)}
.article-section{font-size:12px;color:#7a6855;margin-top:5px}
.article-close{border:0;background:#813d12;color:#fff;width:38px;height:38px;border-radius:50%;font-size:22px;cursor:pointer;flex:none}
.article-body{padding:24px}
.article-body p{color:#4e3d2c}
.article-body h3{color:#71330d;margin:22px 0 8px}
.article-note{margin-top:22px;padding:14px 16px;border-left:4px solid #b67b2f;background:#fff2d8;border-radius:8px;color:#5f4d3a;font-size:13px}
.article-actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:22px}
.article-actions a,.article-actions button{display:inline-block;border:0;border-radius:22px;padding:10px 16px;background:#813d12;color:#fff;font-weight:700;cursor:pointer}
.article-actions .secondary{background:#f1dfc4;color:#71330d}
.topic-link{cursor:pointer}
@media(max-width:620px){.article-modal{padding:8px}.article-box{margin:2vh auto;border-radius:16px}.article-head,.article-body{padding:17px}.article-head h2{font-size:22px}}


/* V3 AUTH + ADMIN */
.auth-bar{display:flex;justify-content:flex-end;gap:8px;align-items:center;margin:12px 0}
.auth-btn{border:0;border-radius:999px;padding:9px 15px;background:#813d12;color:#fff;font-weight:700;cursor:pointer}
.auth-btn.alt{background:#f1dfc4;color:#71330d}
.auth-user{font-size:13px;color:#71330d;font-weight:700}
.auth-modal{position:fixed;inset:0;background:rgba(35,18,8,.72);display:none;z-index:10000;padding:18px;overflow:auto}
.auth-modal.open{display:block}
.auth-box{max-width:560px;margin:5vh auto;background:#fffaf1;border:1px solid #dfc39d;border-radius:20px;box-shadow:0 24px 70px rgba(0,0,0,.3);overflow:hidden}
.auth-head{padding:18px 20px;background:#f1dfc4;display:flex;justify-content:space-between;align-items:center}
.auth-head h2{margin:0;color:#71330d}
.auth-body{padding:20px}
.auth-body label{display:block;font-weight:700;margin:11px 0 6px;color:#5d351b}
.auth-body input,.auth-body textarea,.auth-body select{width:100%;box-sizing:border-box;padding:11px 12px;border:1px solid #d6b78b;border-radius:10px;background:#fff;color:#382515;font:inherit}
.auth-body textarea{min-height:150px;resize:vertical}
.auth-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:14px}
.auth-msg{margin:10px 0;padding:10px 12px;border-radius:10px;background:#f7ead7;color:#71330d;display:none}
.admin-list{max-height:300px;overflow:auto;border:1px solid #dfc39d;border-radius:12px;margin:12px 0}
.admin-row{padding:10px;border-bottom:1px solid #ead9c2;display:flex;justify-content:space-between;gap:10px;align-items:center}
.admin-row:last-child{border-bottom:0}
.admin-row small{display:block;color:#76583e}
.locked-note{padding:14px;border-radius:12px;background:#f8ead5;border:1px solid #e1c49d;color:#6d401b}
@media(max-width:620px){.auth-box{margin:2vh auto}.auth-body{padding:15px}.admin-row{align-items:flex-start;flex-direction:column}}

b:includable.script:
    (function() {
      var items = ;
      var msgs = ;
      var config = ;

// 
      var cursor = null;
      if (items && items.length > 0) {
        cursor = parseInt(items[items.length - 1].timestamp) + 1;
      }

      var bodyFromEntry = function(entry) {
        var text = (entry &&
                    ((entry.content && entry.content.$t) ||
                     (entry.summary && entry.summary.$t))) ||
            '';
        if (entry && entry.gd$extendedProperty) {
          for (var k in entry.gd$extendedProperty) {
            if (entry.gd$extendedProperty[k].name == 'blogger.contentRemoved') {
              return '<span class="deleted-comment">' + text + '</span>';
            }
          }
        }
        return text;
      }

      var parse = function(data) {
        cursor = null;
        var comments = [];
        if (data && data.feed && data.feed.entry) {
          for (var i = 0, entry; entry = data.feed.entry[i]; i++) {
            var comment = {};
            // comment ID, parsed out of the original id format
            var id = /blog-(\d+).post-(\d+)/.exec(entry.id.$t);
            comment.id = id ? id[2] : null;
            comment.body = bodyFromEntry(entry);
            comment.timestamp = Date.parse(entry.published.$t) + '';
            if (entry.author && entry.author.constructor === Array) {
              var auth = entry.author[0];
              if (auth) {
                comment.author = {
                  name: (auth.name ? auth.name.$t : undefined),
                  profileUrl: (auth.uri ? auth.uri.$t : undefined),
                  avatarUrl: (auth.gd$image ? auth.gd$image.src : undefined)
                };
              }
            }
            if (entry.link) {
              if (entry.link[2]) {
                comment.link = comment.permalink = entry.link[2].href;
              }
              if (entry.link[3]) {
                var pid = /.*comments\/default\/(\d+)\?.*/.exec(entry.link[3].href);
                if (pid && pid[1]) {
                  comment.parentId = pid[1];
                }
              }
            }
            comment.deleteclass = 'item-control blog-admin';
            if (entry.gd$extendedProperty) {
              for (var k in entry.gd$extendedProperty) {
                if (entry.gd$extendedProperty[k].name == 'blogger.itemClass') {
                  comment.deleteclass += ' ' + entry.gd$extendedProperty[k].value;
                } else if (entry.gd$extendedProperty[k].name == 'blogger.displayTime') {
                  comment.displayTime = entry.gd$extendedProperty[k].value;
                }
              }
            }
            comments.push(comment);
          }
        }
        return comments;
      };

      var paginator = function(callback) {
        if (hasMore()) {
          var url = config.feed + '?alt=json&v=2&orderby=published&reverse=false&max-results=50';
          if (cursor) {
            url += '&published-min=' + new Date(cursor).toISOString();
          }
          window.bloggercomments = function(data) {
            var parsed = parse(data);
            cursor = parsed.length < 50 ? null
                : parseInt(parsed[parsed.length - 1].timestamp) + 1
            callback(parsed);
            window.bloggercomments = null;
          }
          url += '&callback=bloggercomments';
          var script = document.createElement('script');
          script.type = 'text/javascript';
          script.src = url;
          document.getElementsByTagName('head')[0].appendChild(script);
        }
      };
      var hasMore = function() {
        return !!cursor;
      };
      var getMeta = function(key, comment) {
        if ('iswriter' == key) {
          var matches = !!comment.author
              && comment.author.name == config.authorName
              && comment.author.profileUrl == config.authorUrl;
          return matches ? 'true' : '';
        } else if ('deletelink' == key) {
          return config.baseUri + '/comment/delete/'
               + config.blogId + '/' + comment.id;
        } else if ('deleteclass' == key) {
          return comment.deleteclass;
        }
        return '';
      };

      var replybox = null;
      var replyUrlParts = null;
      var replyParent = undefined;

      var onReply = function(commentId, domId) {
        if (replybox == null) {
          // lazily cache replybox, and adjust to suit this style:
          replybox = document.getElementById('comment-editor');
          if (replybox != null) {
            replybox.height = '250px';
            replybox.style.display = 'block';
            replyUrlParts = replybox.src.split('#');
          }
        }
        if (replybox && (commentId !== replyParent)) {
          replybox.src = '';
          document.getElementById(domId).insertBefore(replybox, null);
          replybox.src = replyUrlParts[0]
              + (commentId ? '&parentID=' + commentId : '')
              + '#' + replyUrlParts[1];
          replyParent = commentId;
        }
      };

      var hash = (window.location.hash || '#').substring(1);
      var startThread, targetComment;
      if (/^comment-form_/.test(hash)) {
        startThread = hash.substring('comment-form_'.length);
      } else if (/^c[0-9]+$/.test(hash)) {
        targetComment = hash.substring(1);
      }

      // Configure commenting API:
      var configJso = {
        'maxDepth': config.maxThreadDepth
      };
      var provider = {
        'id': config.postId,
        'data': items,
        'loadNext': paginator,
        'hasMore': hasMore,
        'getMeta': getMeta,
        'onReply': onReply,
        'rendered': true,
        'initComment': targetComment,
        'initReplyThread': startThread,
        'config': configJso,
        'messages': msgs
      };

      var render = function() {
        if (window.goog && window.goog.comments) {
          var holder = document.getElementById('comment-holder');
          window.goog.comments.render(holder, provider);
        }
      };

      // render now, or queue to render when library loads:
      if (window.goog && window.goog.comments) {
        render();
      } else {
        window.goog = window.goog || {};
        window.goog.comments = window.goog.comments || {};
        window.goog.comments.loadQueue = window.goog.comments.loadQueue || [];
        window.goog.comments.loadQueue.push(render);
      }
    })();
//

body.script:
(function(){
'use strict';

var ADMIN_ID='Admin';
/* Browser-only demo authentication: not a substitute for a server-side account system. */
var ADMIN_HASH=''; 
var USERS_KEY='gob_users_v4';
var SESSION_KEY='gob_session_v4';
var OVERRIDE_KEY='gob_article_overrides_v4';

function hashText(str){
  var h1=2166136261>>>0,h2=2246822519>>>0,i,c;
  for(i=0;i<str.length;i++){
    c=str.charCodeAt(i);
    h1^=c; h1=Math.imul(h1,16777619)>>>0;
    h2^=(c+31); h2=Math.imul(h2,3266489917)>>>0;
  }
  return ('00000000'+h1.toString(16)).slice(-8)+('00000000'+h2.toString(16)).slice(-8);
}
ADMIN_HASH=hashText('Gadadhar@Pandit');

function readStore(storage,key,fallback){
  try{var v=storage.getItem(key);return v===null?fallback:JSON.parse(v)}
  catch(e){return fallback}
}
function writeStore(storage,key,value){
  try{storage.setItem(key,JSON.stringify(value));return true}catch(e){return false}
}
function getUsers(){return readStore(window.localStorage,USERS_KEY,[])}
function setUsers(x){return writeStore(window.localStorage,USERS_KEY,x)}
function getSession(){return readStore(window.sessionStorage,SESSION_KEY,null)}
function setSession(x){return writeStore(window.sessionStorage,SESSION_KEY,x)}
function clearSession(){try{window.sessionStorage.removeItem(SESSION_KEY)}catch(e){}}
function getOverrides(){return readStore(window.localStorage,OVERRIDE_KEY,{})}
function saveOverrides(x){return writeStore(window.localStorage,OVERRIDE_KEY,x)}

var authModal=document.getElementById('authModal');
var adminModal=document.getElementById('adminModal');
var loginForm=document.getElementById('loginForm');
var registerForm=document.getElementById('registerForm');
var msg=document.getElementById('authMsg');
var statusEl=document.getElementById('authStatus');
var loginBtn=document.getElementById('loginBtn');
var regBtn=document.getElementById('registerBtn');
var adminBtn=document.getElementById('adminBtn');
var logoutBtn=document.getElementById('logoutBtn');

function showMsg(t){if(msg){msg.textContent=t;msg.style.display='block'}}
function openLogin(){
  if(!authModal)return;
  authModal.classList.add('open');authModal.setAttribute('aria-hidden','false');
  loginForm.style.display='block';registerForm.style.display='none';
  document.getElementById('authTitle').textContent='à¦¸à¦¦à¦¸à§à¦¯ à¦²à¦—à¦‡à¦¨';
  if(msg)msg.style.display='none';
}
function openRegister(){
  if(!authModal)return;
  authModal.classList.add('open');authModal.setAttribute('aria-hidden','false');
  loginForm.style.display='none';registerForm.style.display='block';
  document.getElementById('authTitle').textContent='à¦¨à¦¤à§à¦¨ à¦¸à¦¦à¦¸à§à¦¯ à¦¨à¦¿à¦¬à¦¨à§à¦§à¦¨';
  if(msg)msg.style.display='none';
}
function closeAuth(){
  if(authModal){authModal.classList.remove('open');authModal.setAttribute('aria-hidden','true')}
}
function isLoggedIn(){return !!getSession()}
function isAdmin(){var x=getSession();return !!(x&&x.role==='admin')}

function updateUI(){
  var x=getSession();
  if(statusEl)statusEl.textContent=x?(x.role==='admin'?'Admin: '+x.name:'à¦¸à¦¦à¦¸à§à¦¯: '+x.name):'à¦…à¦¤à¦¿à¦¥à¦¿';
  if(loginBtn)loginBtn.style.display=x?'none':'inline-block';
  if(regBtn)regBtn.style.display=x?'none':'inline-block';
  if(logoutBtn)logoutBtn.style.display=x?'inline-block':'none';
  if(adminBtn)adminBtn.style.display=isAdmin()?'inline-block':'none';
}

function finishLogin(x){
  setSession(x);updateUI();closeAuth();
  if(window.GOBAuth && window.GOBAuth.pending){
    var id=window.GOBAuth.pending;window.GOBAuth.pending=null;
    if(typeof window.GOBOpenArticle==='function')window.GOBOpenArticle(id);
  }
}

if(loginBtn)loginBtn.onclick=openLogin;
if(regBtn)regBtn.onclick=openRegister;
if(logoutBtn)logoutBtn.onclick=function(){clearSession();updateUI();location.hash='';};
var closeAuthBtn=document.getElementById('authClose');
if(closeAuthBtn)closeAuthBtn.onclick=closeAuth;
var swReg=document.getElementById('switchRegister');
if(swReg)swReg.onclick=openRegister;
var swLogin=document.getElementById('switchLogin');
if(swLogin)swLogin.onclick=openLogin;

var doRegister=document.getElementById('doRegister');
if(doRegister)doRegister.onclick=function(){
  var name=document.getElementById('regName').value.trim();
  var u=document.getElementById('regUser').value.trim().toLowerCase();
  var p=document.getElementById('regPass').value;
  var p2=document.getElementById('regPass2').value;
  if(!name||!u||!p||!p2)return showMsg('à¦¸à¦¬ à¦¤à¦¥à§à¦¯ à¦ªà§‚à¦°à¦£ à¦•à¦°à§à¦¨à¥¤');
  if(p.length<6)return showMsg('Password à¦•à¦®à¦ªà¦•à§à¦·à§‡ 6 à¦…à¦•à§à¦·à¦°à§‡à¦° à¦•à¦°à§à¦¨à¥¤');
  if(p!==p2)return showMsg('à¦¦à§à¦‡à¦Ÿà¦¿ Password à¦à¦•à¦‡ à¦¨à§Ÿà¥¤');
  if(u===ADMIN_ID.toLowerCase())return showMsg('à¦à¦‡ User ID à¦¸à¦‚à¦°à¦•à§à¦·à¦¿à¦¤à¥¤');
  var users=getUsers();
  if(users.some(function(a){return a.user===u}))return showMsg('à¦à¦‡ User ID à¦†à¦—à§‡ à¦¥à§‡à¦•à§‡à¦‡ à¦†à¦›à§‡à¥¤');
  users.push({name:name,user:u,hash:hashText(p),role:'member',created:new Date().toISOString()});
  if(!setUsers(users))return showMsg('Registration à¦¸à¦‚à¦°à¦•à§à¦·à¦£ à¦•à¦°à¦¾ à¦¯à¦¾à¦šà§à¦›à§‡ à¦¨à¦¾à¥¤ Browser storage à¦…à¦¨à§à¦®à¦¤à¦¿ à¦ªà¦°à§€à¦•à§à¦·à¦¾ à¦•à¦°à§à¦¨à¥¤');
  finishLogin({name:name,user:u,role:'member'});
  alert('à¦¨à¦¿à¦¬à¦¨à§à¦§à¦¨ à¦¸à¦«à¦² à¦¹à§Ÿà§‡à¦›à§‡à¥¤ à¦à¦–à¦¨ à¦†à¦ªà¦¨à¦¿ à¦ªà§‚à¦°à§à¦£ article à¦ªà§œà¦¤à§‡ à¦ªà¦¾à¦°à¦¬à§‡à¦¨à¥¤');
};

var doLogin=document.getElementById('doLogin');
if(doLogin)doLogin.onclick=function(){
  var u=document.getElementById('loginUser').value.trim();
  var p=document.getElementById('loginPass').value;
  if(!u||!p)return showMsg('User ID à¦à¦¬à¦‚ Password à¦¦à¦¿à¦¨à¥¤');
  if(u.toLowerCase()===ADMIN_ID.toLowerCase()){
    if(hashText(p)===ADMIN_HASH){finishLogin({name:'Admin',user:ADMIN_ID,role:'admin'});return}
    return showMsg('Admin credentials à¦¸à¦ à¦¿à¦• à¦¨à§Ÿà¥¤');
  }
  var users=getUsers();
  var found=null;
  for(var i=0;i<users.length;i++){if(users[i].user===u.toLowerCase()){found=users[i];break}}
  if(!found)return showMsg('User à¦ªà¦¾à¦“à§Ÿà¦¾ à¦¯à¦¾à§Ÿà¦¨à¦¿à¥¤ à¦†à¦—à§‡ Registration à¦•à¦°à§à¦¨à¥¤');
  if(hashText(p)!==found.hash)return showMsg('Password à¦¸à¦ à¦¿à¦• à¦¨à§Ÿà¥¤');
  finishLogin({name:found.name,user:found.user,role:'member'});
};

if(authModal)authModal.addEventListener('click',function(e){if(e.target===authModal)closeAuth()});
document.addEventListener('keydown',function(e){
  if(e.key==='Escape'){
    closeAuth();
    if(adminModal)adminModal.classList.remove('open');
  }
});

/* Admin article editor */
function currentData(){
  var o=getOverrides();
  return (window.GOB_DATA||[]).map(function(x){
    return o[String(x.id)]?Object.assign({},x,o[String(x.id)]):x;
  });
}
function populateAdmin(){
  var sel=document.getElementById('articleSelect');
  if(!sel)return;
  sel.innerHTML='';
  currentData().forEach(function(x){
    var op=document.createElement('option');
    op.value=x.id;op.textContent=x.id+' â€” '+x.title;sel.appendChild(op);
  });
  loadAdminArticle();
}
function loadAdminArticle(){
  var sel=document.getElementById('articleSelect');if(!sel)return;
  var item=currentData().find(function(x){return String(x.id)===String(sel.value)});
  if(!item)return;
  document.getElementById('editTitle').value=item.title||'';
  document.getElementById('editSection').value=item.section||'';
  document.getElementById('editIntro').value=item.intro||'';
  document.getElementById('editBody').value=item.body||'';
  document.getElementById('editNote').value=item.note||'';
  document.getElementById('editHref').value=item.href||'';
}
function openAdmin(){
  if(!isAdmin())return openLogin();
  if(!adminModal)return;
  populateAdmin();
  adminModal.classList.add('open');adminModal.setAttribute('aria-hidden','false');
}
if(adminBtn)adminBtn.onclick=openAdmin;
var adminClose=document.getElementById('adminClose');
if(adminClose)adminClose.onclick=function(){adminModal.classList.remove('open');adminModal.setAttribute('aria-hidden','true')};
var articleSelect=document.getElementById('articleSelect');
if(articleSelect)articleSelect.onchange=loadAdminArticle;
var saveArticle=document.getElementById('saveArticle');
if(saveArticle)saveArticle.onclick=function(){
  var sel=document.getElementById('articleSelect');if(!sel)return;
  var id=String(sel.value),o=getOverrides();
  o[id]={
    title:document.getElementById('editTitle').value,
    section:document.getElementById('editSection').value,
    intro:document.getElementById('editIntro').value,
    body:document.getElementById('editBody').value,
    note:document.getElementById('editNote').value,
    href:document.getElementById('editHref').value
  };
  if(!saveOverrides(o)){document.getElementById('adminMsg').textContent='Save failed: browser storage unavailable.';return}
  document.getElementById('adminMsg').textContent='Article saved/published in this browser.';
};
var resetArticle=document.getElementById('resetArticle');
if(resetArticle)resetArticle.onclick=function(){
  var sel=document.getElementById('articleSelect');if(!sel)return;
  var o=getOverrides();delete o[String(sel.value)];saveOverrides(o);loadAdminArticle();
  document.getElementById('adminMsg').textContent='à¦®à§‚à¦² Content restore à¦¹à§Ÿà§‡à¦›à§‡à¥¤';
};
if(adminModal)adminModal.addEventListener('click',function(e){if(e.target===adminModal)adminModal.classList.remove('open')});

window.GOBAuth={
  isLoggedIn:isLoggedIn,
  openLogin:openLogin,
  openRegister:openRegister,
  pending:null
};
window.GOBOpenAdmin=openAdmin;
updateUI();
})();
